style.css:
@-moz-document domain("codepen.io") {
@font-face {
        font-family: 'Hack';
        src: local('Google Sans Flex'), 
             local('Google Sans'), 
             local('Product Sans');

        font-weight: normal;
        font-style: normal;
    }


    .CodeMirror,           
    .cm-editor,            
    .monaco-editor,       
    .CodeMirror-lines,
    .cm-content,
    code, 
    kbd, 
    samp, 
    pre {
        font-family: 'Google Sans Flex', 'Google Sans', 'Hack', sans-serif !important;
        
        
        letter-spacing: 0.3px; 
    }
}
